<?php
defined('ABSPATH')||exit;
class SMF_Quality{
 public static function init(){add_action('admin_menu',array(__CLASS__,'menu'));}
 public static function menu(){add_submenu_page('sync-meta-flow','Customer Quality','Customer Quality','manage_woocommerce','smf-quality',array(__CLASS__,'render'));}
 private static function decorate($r){$o=(int)$r['orders'];$d=(int)$r['delivered'];$c=(int)$r['confirmed'];$ret=(int)$r['returned'];$r['net']=max(0,$r['delivered_revenue']-$r['returned_revenue']);$r['confirmation_rate']=$o?$c/$o*100:0;$r['delivery_rate']=$o?$d/$o*100:0;$r['cancel_rate']=$o?$r['cancelled']/$o*100:0;$r['return_rate']=$d?$ret/$d*100:0;$r['net_roas']=$r['spend']>0?$r['net']/$r['spend']:0;$r['revenue_per_order']=$o?$r['net']/$o:0;$r['quality_score']=round(max(0,min(100,$r['delivery_rate']*.35+$r['confirmation_rate']*.20+max(0,100-$r['cancel_rate'])*.20+max(0,100-$r['return_rate'])*.15+min(100,$r['net_roas']/3*100)*.10)),1);$r['decision']=$o===0?'NO DATA':($r['quality_score']>=75?'SCALE':($r['quality_score']>=50?'WATCH':'KILL'));return $r;}
 private static function blank($name=''){return array('campaign'=>$name,'campaign_id'=>'','orders'=>0,'confirmed'=>0,'shipped'=>0,'delivered'=>0,'cancelled'=>0,'returned'=>0,'purchase_revenue'=>0,'delivered_revenue'=>0,'returned_revenue'=>0,'spend'=>0,'net'=>0);}
 public static function performance($since,$until,$currency='BDT'){global $wpdb;$et=$wpdb->prefix.'smf_order_events';$st=$wpdb->prefix.'smf_campaign_spend';$p=$wpdb->get_results($wpdb->prepare("SELECT order_id FROM $et WHERE event_type='purchase' AND created_at >= %s AND created_at < DATE_ADD(%s,INTERVAL 1 DAY)",$since.' 00:00:00',$until.' 00:00:00'));$ids=array();foreach($p as $x)$ids[(int)$x->order_id]=1;if(!$ids){$z=self::blank('ALL');return array('summary'=>self::decorate($z),'campaigns'=>array());}$ph=implode(',',array_fill(0,count($ids),'%d'));$ev=$wpdb->get_results($wpdb->prepare("SELECT order_id,event_type,new_status,metadata FROM $et WHERE order_id IN ($ph) ORDER BY order_id,created_at,id",array_keys($ids)));$orders=array();foreach($ev as $e){$id=(int)$e->order_id;if(!isset($orders[$id]))$orders[$id]=array('total'=>0,'currency'=>'','campaign'=>'','campaign_id'=>'','purchased'=>false,'confirmed'=>false,'shipped'=>false,'delivered'=>false,'cancelled'=>false,'returned'=>false);$m=$e->metadata?json_decode($e->metadata,true):array();if(isset($m['order_total']))$orders[$id]['total']=(float)$m['order_total'];if(!empty($m['currency']))$orders[$id]['currency']=sanitize_text_field($m['currency']);$orders[$id]['campaign']=sanitize_text_field((string)($m['last_campaign']??$m['campaign']??$orders[$id]['campaign']));$orders[$id]['campaign_id']=sanitize_text_field((string)($m['last_campaign_id']??$m['campaign_id']??$orders[$id]['campaign_id']));if($e->event_type==='purchase')$orders[$id]['purchased']=true;$s=(string)$e->new_status;if(in_array($s,array('smf-confirmed','processing','on-hold','completed','smf-shipped','smf-delivered'),true))$orders[$id]['confirmed']=true;if(in_array($s,array('smf-shipped','smf-delivered','completed'),true))$orders[$id]['shipped']=true;if(in_array($s,array('smf-delivered','completed'),true))$orders[$id]['delivered']=true;if($s==='cancelled')$orders[$id]['cancelled']=true;if(in_array($s,array('smf-returned','refunded'),true))$orders[$id]['returned']=true;}$sp=$wpdb->get_results($wpdb->prepare("SELECT campaign_id,amount FROM $st WHERE spend_date BETWEEN %s AND %s AND currency=%s AND campaign_id<>''",$since,$until,$currency));$spend=array();foreach($sp as $x)$spend[(string)$x->campaign_id]=($spend[(string)$x->campaign_id]??0)+(float)$x->amount;$cs=array();foreach($orders as $o){if(!$o['purchased']||strtoupper($o['currency'])!==strtoupper($currency))continue;$n=$o['campaign']?:'Direct / Unattributed';if(!isset($cs[$n]))$cs[$n]=self::blank($n);$cs[$n]['campaign_id']=$o['campaign_id'];$cs[$n]['orders']++;$cs[$n]['purchase_revenue']+=$o['total'];foreach(array('confirmed','shipped','cancelled') as $f)if($o[$f])$cs[$n][$f]++;if($o['delivered']){$cs[$n]['delivered']++;$cs[$n]['delivered_revenue']+=$o['total'];}if($o['returned']){$cs[$n]['returned']++;$cs[$n]['returned_revenue']+=$o['total'];}}foreach($cs as &$row){$row['spend']=$spend[$row['campaign_id']]??0;}unset($row);$sum=self::blank('ALL');foreach($cs as $r)foreach(array('orders','confirmed','shipped','delivered','cancelled','returned','purchase_revenue','delivered_revenue','returned_revenue','spend') as $f)$sum[$f]+=$r[$f];$out=array();foreach($cs as $r)$out[]=self::decorate($r);usort($out,function($a,$b){return $b['quality_score']<=>$a['quality_score'];});return array('summary'=>self::decorate($sum),'campaigns'=>$out);}
 public static function render(){if(!current_user_can('manage_woocommerce'))return;$days=isset($_GET['period'])&&in_array(absint($_GET['period']),array(7,30,90),true)?absint($_GET['period']):30;$until=current_time('Y-m-d');$since=wp_date('Y-m-d',strtotime('-'.($days-1).' days',current_time('timestamp')));$currency=isset($_GET['currency'])?strtoupper(sanitize_text_field(wp_unslash($_GET['currency']))):'BDT';$r=self::performance($since,$until,$currency);$s=$r['summary'];?><div class="wrap smf-wrap smf-settings"><div class="smf-header"><div><h1>Customer Quality</h1><p>Campaign quality across confirmation, shipment, delivery, cancellation, return and net revenue.</p></div><a class="button" href="<?php echo esc_url(admin_url('admin.php?page=sync-meta-flow'));?>">← Dashboard</a></div><div class="smf-period-bar"><strong><?php echo esc_html($currency);?> · Quality</strong><?php foreach(array(7,30,90) as $p):?><a class="button <?php echo $days===$p?'button-primary':'';?>" href="<?php echo esc_url(admin_url('admin.php?page=smf-quality&period='.$p.'&currency='.rawurlencode($currency)));?>"><?php echo esc_html($p);?> days</a><?php endforeach;?></div><div class="smf-cards"><div class="smf-card"><span>Quality Score</span><strong><?php echo esc_html(number_format_i18n($s['quality_score'],1));?>/100</strong><small>Weighted quality</small></div><div class="smf-card"><span>Delivery Rate</span><strong><?php echo esc_html(number_format_i18n($s['delivery_rate'],1));?>%</strong><small><?php echo esc_html($s['delivered']);?> / <?php echo esc_html($s['orders']);?></small></div><div class="smf-card"><span>Cancellation</span><strong><?php echo esc_html(number_format_i18n($s['cancel_rate'],1));?>%</strong><small><?php echo esc_html($s['cancelled']);?> cancelled</small></div><div class="smf-card"><span>Net Revenue</span><strong><?php echo esc_html(number_format_i18n($s['net'],2));?></strong><small><?php echo esc_html(number_format_i18n($s['net_roas'],2));?>× net ROAS</small></div></div><div class="smf-revenue-grid"><div><span>Confirmation</span><strong><?php echo esc_html(number_format_i18n($s['confirmation_rate'],1));?>%</strong></div><div><span>Shipped</span><strong><?php echo esc_html($s['shipped']);?></strong></div><div><span>Return Rate</span><strong><?php echo esc_html(number_format_i18n($s['return_rate'],1));?>%</strong></div><div><span>Revenue / Order</span><strong><?php echo esc_html(number_format_i18n($s['revenue_per_order'],2));?></strong></div></div><div class="smf-panel"><h2>Campaign Quality</h2><p class="smf-muted">Last-touch attribution is used for operational decisions. Full event history is used, so later delivery/cancellation/return events update the purchase cohort.</p><div class="smf-table-wrap"><table class="smf-table"><thead><tr><th>Campaign</th><th>Score</th><th>Orders</th><th>Confirmed</th><th>Shipped</th><th>Delivered</th><th>Cancelled</th><th>Returned</th><th>Delivery %</th><th>Cancel %</th><th>Return %</th><th>Net ROAS</th><th>Decision</th></tr></thead><tbody><?php if($r['campaigns']):foreach($r['campaigns'] as $x):?><tr><td><strong><?php echo esc_html($x['campaign']);?></strong><?php if($x['campaign_id']):?><br><small><?php echo esc_html($x['campaign_id']);?></small><?php endif;?></td><td><strong><?php echo esc_html(number_format_i18n($x['quality_score'],1));?></strong></td><td><?php echo esc_html($x['orders']);?></td><td><?php echo esc_html($x['confirmed']);?></td><td><?php echo esc_html($x['shipped']);?></td><td><?php echo esc_html($x['delivered']);?></td><td><?php echo esc_html($x['cancelled']);?></td><td><?php echo esc_html($x['returned']);?></td><td><?php echo esc_html(number_format_i18n($x['delivery_rate'],1));?>%</td><td><?php echo esc_html(number_format_i18n($x['cancel_rate'],1));?>%</td><td><?php echo esc_html(number_format_i18n($x['return_rate'],1));?>%</td><td><?php echo esc_html(number_format_i18n($x['net_roas'],2));?>×</td><td><span class="smf-decision smf-decision-<?php echo esc_attr(strtolower(str_replace(' ','-',$x['decision'])));?>"><?php echo esc_html($x['decision']);?></span></td></tr><?php endforeach;else:?><tr><td colspan="13">No purchase data for this period.</td></tr><?php endif;?></tbody></table></div><p class="smf-muted"><strong>Score:</strong> delivery 35% · confirmation 20% · low cancellation 20% · low return 15% · net ROAS 10%. SCALE ≥75 · WATCH 50–74.9 · KILL &lt;50. This is a transparent operational heuristic, not Meta attribution or a profitability guarantee.</p></div></div><?php }
}